package me.arcanebrewery.arcaneBrewery.application.research;
import me.arcanebrewery.arcaneBrewery.application.alchemy.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SpecialistProcessTest {
 static EffectProfile profile(){return new EffectProfile(1,EffectCapabilities.STARTER_INFUSER,List.of(new EffectProfile.Entry(ProfileEffect.HASTE,50,1,false),new EffectProfile.Entry(ProfileEffect.HUNGER,15,0,true)),EffectProfile.Safety.SAFE,100);}
 @Test void researchChargesExactLevelsOnceAndPersistsDurableFlags(){var p=new ResearchProgress(Set.of());var type=SpecialistType.REAGENT_PROCESSOR;var known=new HashSet<>(type.materials);var purchase=p.purchase(type,known,false,20);assertEquals(14,purchase.remainingLevels());var loaded=ResearchProgress.decode(purchase.progress().encode());assertEquals(purchase.progress(),loaded);assertTrue(type.missing(loaded.earned(),Set.of(),false,0).isEmpty());assertThrows(IllegalStateException.class,()->loaded.purchase(type,known,false,20));assertTrue(p.earned().isEmpty());}
 @Test void missingKnowledgeXpAndPrerequisiteResearchCannotCharge(){var p=new ResearchProgress(Set.of());assertThrows(IllegalStateException.class,()->p.purchase(SpecialistType.REAGENT_PROCESSOR,Set.of(),false,99));assertThrows(IllegalStateException.class,()->p.purchase(SpecialistType.REAGENT_PROCESSOR,Set.copyOf(SpecialistType.REAGENT_PROCESSOR.materials),false,5));assertThrows(IllegalStateException.class,()->p.purchase(SpecialistType.DURATION_INFUSER,Set.copyOf(SpecialistType.DURATION_INFUSER.materials),true,99));assertThrows(IllegalStateException.class,()->new ResearchProgress(Set.of("REAGENT_PROCESSOR")).purchase(SpecialistType.DURATION_INFUSER,Set.copyOf(SpecialistType.DURATION_INFUSER.materials),false,99));}
 @Test void invalidResearchVersionAndIdsFailClosed(){assertThrows(IllegalArgumentException.class,()->ResearchProgress.decode("9:REAGENT_PROCESSOR"));assertThrows(IllegalArgumentException.class,()->ResearchProgress.decode("1:UNKNOWN"));assertThrows(IllegalArgumentException.class,()->new ResearchProgress(Set.of()).purchase(SpecialistType.REAGENT_PROCESSOR,Set.of(),false,-1));}
 @Test void durationIsUsefulButTradesTierAndNeverExceedsTenMinutes(){var out=SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,profile(),0,null);assertEquals(600,out.profile().effects().getFirst().seconds());assertEquals(0,out.profile().effects().getFirst().amplifier());assertEquals(15,out.profile().effects().getLast().seconds());assertEquals(profile().safety(),out.profile().safety());assertThrows(IllegalStateException.class,()->SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,out.profile(),out.history(),null));}
 @Test void concentrationRaisesOnlyEligibleTiersWithSevereDurationTradeoff(){var result=SpecialistProcess.apply(SpecialistType.ESSENCE_CONCENTRATOR,profile(),0,null);assertEquals(2,result.profile().effects().getFirst().amplifier());assertEquals(17,result.profile().effects().getFirst().seconds());var combat=new EffectProfile(1,EffectCapabilities.STARTER_INFUSER,List.of(new EffectProfile.Entry(ProfileEffect.STRENGTH,30,0,false)),EffectProfile.Safety.SAFE,100);var strong=SpecialistProcess.apply(SpecialistType.ESSENCE_CONCENTRATOR,combat,0,null).profile().effects().getFirst();assertEquals(1,strong.amplifier());assertEquals(10,strong.seconds());assertEquals(0,EffectCapabilities.ESSENCE_CONCENTRATOR.cap(ProfileEffect.RESISTANCE).amplifier());}
 @Test void operationOrderingCannotMakeTenMinuteHighTierEffects(){var longResult=SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,profile(),0,null);var concentrated=SpecialistProcess.apply(SpecialistType.ESSENCE_CONCENTRATOR,longResult.profile(),longResult.history(),null);assertTrue(concentrated.profile().effects().getFirst().seconds()<=90);assertEquals(1,concentrated.profile().effects().getFirst().amplifier());assertThrows(IllegalStateException.class,()->SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,concentrated.profile(),concentrated.history(),null));}
 @Test void purificationRemovesExactlyTheSelectedUnwantedEffect(){var result=SpecialistProcess.apply(SpecialistType.PURIFICATION_CHAMBER,profile(),0,ProfileEffect.HUNGER);assertEquals(List.of(profile().effects().getFirst()),result.profile().effects());assertThrows(IllegalArgumentException.class,()->SpecialistProcess.apply(SpecialistType.PURIFICATION_CHAMBER,profile(),0,ProfileEffect.SPEED));assertThrows(IllegalArgumentException.class,()->SpecialistProcess.apply(SpecialistType.PURIFICATION_CHAMBER,profile(),0,ProfileEffect.HASTE));assertThrows(IllegalStateException.class,()->SpecialistProcess.apply(SpecialistType.PURIFICATION_CHAMBER,result.profile(),result.history(),ProfileEffect.HUNGER));}
 @Test void resultsAreDeterministicAndVersionedProfilesStillDecode(){var a=SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,profile(),0,null);assertEquals(a,SpecialistProcess.apply(SpecialistType.DURATION_INFUSER,profile(),0,null));var codec=new EffectProfileCodec();assertEquals(a.profile(),codec.decode(codec.encode(a.profile())));assertEquals(profile(),codec.decode(codec.encode(profile())));}
 @Test void recoveryOnlyReleasesCapturedOutputAtDeadline(){var state=new SpecialistState(SpecialistType.REAGENT_PROCESSOR,true,10000,0);var saved=state.encode();assertEquals(state,SpecialistState.decode(saved).complete(9999));assertEquals(0,SpecialistState.decode(saved).complete(10000).readyAt());assertTrue(SpecialistState.decode(saved).complete(20000).built());assertThrows(IllegalArgumentException.class,()->SpecialistState.decode("bad"));assertThrows(IllegalArgumentException.class,()->new SpecialistState(SpecialistType.REAGENT_PROCESSOR,false,10,0));}
 @Test void concentrationRejectsFamiliesThatCannotGainStrength(){var input=new EffectProfile(1,EffectCapabilities.STARTER_INFUSER,List.of(new EffectProfile.Entry(ProfileEffect.RESISTANCE,20,0,false)),EffectProfile.Safety.SAFE,100);assertThrows(IllegalArgumentException.class,()->SpecialistProcess.apply(SpecialistType.ESSENCE_CONCENTRATOR,input,0,null));}
}
